define(['jquery', 'Magento_Ui/js/modal/modal', 'uiComponent', 'ammenu_helpers', 'underscore', 'mage/translate'], function($, modal, Component, helpers, _) {
    'use strict';
    return Component.extend({
        defaults: {
            templates: {
                itemsAccordion: 'Amasty_MegaMenuLite/sidebar_menu/accordion/items/wrapper'
            },
            components: ['index = ammenu_wrapper'],
            imports: {
                hamburger_animation: 'index = ammenu_wrapper:hamburger_animation',
                animation_time: 'index = ammenu_wrapper:animation_time',
                root_templates: 'index = ammenu_wrapper:templates',
                color_settings: 'index = ammenu_wrapper:color_settings',
                settings: 'index = ammenu_wrapper:settings',
                is_hamburger: 'index = ammenu_wrapper:is_hamburger',
                icons: 'index = ammenu_wrapper:icons',
                is_icons_available: 'index = ammenu_wrapper:is_icons_available',
                mobile_class: 'index = ammenu_wrapper:mobile_class',
                isOpen: 'index = ammenu_hamburger_toggle:isOpen',
                activeTab: 'index = ammenu_tabs_wrapper:activeTab',
                hide_view_all_link: 'index = ammenu_wrapper:hide_view_all_link'
            }
        },
        initialize: function() {
            this._super();
            this._initElems(this.source.data.elems);
            return this;
        },
        initObservable: function() {
            this._super().observe({
                elems: [],
                isOpen: false,
                activeTab: 0,
                isAboutOpen: false,
                isMoreOpen: false,
                isLocateOpen: false
            });
            return this;
        },
        toggleItem: function(elem) {
            if (elem.isSubmenuVisible && elem.isSubmenuVisible()) {
                elem.isActive(!elem.isActive());
                elem.rendered(true);
                if (elem.isActive()) {
                    elem.color(elem.level() ? this.color_settings.submenu_text_hover : this.color_settings.main_menu_text_hover);
                } else {
                    elem.color(elem.base_color);
                }
                return false;
            }
            return true;
        },
        _initElems: function(elems) {
            var self = this;
            _.each(elems, function(elem) {
                if (elem.elems.length || elem.mobile_content) {
                    self._initElems(elem.elems);
                }
                self._initElem(elem);
            });
        },
        _initElem: function(elem) {
            var isMobile = this.source.isMobile();
            if (isMobile) {
                elem.isSubmenuVisible(!elem.hide_mobile_content && (elem.elems.length || elem.mobile_content));
            }
            if (isMobile && !this.hide_view_all_link && (elem.elems.length || elem.mobile_content && elem.mobile_content.trim().length > 7 && !elem.hide_mobile_content)) {
                helpers.initAllItemLink(elem, this.color_settings.third_level_menu);
            }
            if (isMobile && elem.mobile_content && !elem.show_mobile_content && elem.elems.length) {
                elem.elems[0].isFocused = false;
            }
            if (elem.level() && !elem.current) {
                elem.color(this.color_settings.third_level_menu);
                elem.base_color = this.color_settings.third_level_menu;
            }
        },
        closeSidebar: function() {
            $('.ammenu-button.-icon.-close').click();
        },
        toggleAbout: function() {
            this.isAboutOpen(!this.isAboutOpen());
        },
        toggleMore: function() {
            this.isMoreOpen(!this.isMoreOpen());
        },
        toggleLocate: function() {
            this.isLocateOpen(!this.isLocateOpen());
        },
        isStoreLoginEnabled: function() {
            return !localStorage.getItem('store_name');
        },
        showStorePopup: function() {
            var modalPopup = $('#login-modal-form');
            if (!modalPopup.hasClass('ui-dialog-content')) {
                modalPopup.modal({
                    type: 'popup',
                    responsive: true,
                    innerScroll: true,
                    buttons: [],
                    modalClass: "popup-center storelogin-popup",
                });
            }
            modalPopup.modal('openModal');
            this.initializeReCaptcha();
        },
        initializeReCaptcha: function() {
            $('#store-login-recaptcha').val('');
            var element_render = 'store-tab-login-recaptcha';
            var validate = 'store-login-recaptcha';
            var renderCaptcha = function() {
                if ($('#' + element_render).children().length === 0) {
                    grecaptcha.render(element_render, {
                        'sitekey': window.recapLoginSiteKey,
                        'theme': "light",
                        'type': "image",
                        'size': "normal",
                        'callback': function(response) {
                            if (response.length > 0) {
                                $('#' + validate).val('success');
                            }
                        }
                    });
                }
            };
            if (typeof grecaptcha !== 'undefined' && grecaptcha.render) {
                if (grecaptcha.ready) {
                    grecaptcha.ready(renderCaptcha);
                } else {
                    renderCaptcha();
                }
            } else {
                var attempts = 0,
                    timer = setInterval(function() {
                        attempts++;
                        if (typeof grecaptcha !== 'undefined' && grecaptcha.render) {
                            clearInterval(timer);
                            renderCaptcha();
                        } else if (attempts > 50) {
                            clearInterval(timer);
                        }
                    }, 200);
            }
        }
    });
});